window.DIFFU_SEARCH_INDEX=[{"type":"Sản phẩm","code":"BDR","title":"Diffu-Therm BDR","desc":"Chất thẩm thấu màu đỏ (bản tiêu chuẩn). Diffu-Therm BDR: penetrant đỏ bản tiêu chuẩn, rửa bằng nước, dải nhiệt 5…50°C, quan sát bằng thuốc hiện hình. Bình xịt 500 ml và can 1–200 L. Fast Group báo giá kèm SDS. Bình xịt aerosol 500 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-bdr/","category":"Chất thẩm thấu PT Diffu-Therm"},{"type":"Sản phẩm","code":"BDR-GL","title":"Diffu-Therm BDR-GL","desc":"Chất thẩm thấu màu đỏ, không phẩm màu azo. Diffu-Therm BDR-GL: penetrant đỏ không phẩm màu azo, rửa bằng nước, dải nhiệt −10…50°C, quan sát được dưới đèn UV. Bình xịt 500 ml và can 1–200 L. RFQ kèm SDS tại Fast Group. Bình xịt aerosol 500 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-bdr-gl/","category":"Chất thẩm thấu PT Diffu-Therm"},{"type":"Sản phẩm","code":"BDR-L","title":"Diffu-Therm BDR-L","desc":"Chất thẩm thấu màu đỏ, không phẩm màu azo. Diffu-Therm BDR-L: penetrant đỏ không phẩm màu azo, rửa bằng nước, làm việc từ −10°C, quan sát được cả dưới đèn UV. Bình xịt 500 ml, can 1–200 L. Fast Group báo giá kèm SDS. Bình xịt aerosol 500 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-bdr-l/","category":"Chất thẩm thấu PT Diffu-Therm"},{"type":"Sản phẩm","code":"BEA","title":"Diffu-Therm BEA","desc":"Thuốc hiện hình, rửa được. Diffu-Therm BEA: thuốc hiện hình (developer) gốc dung môi cho kiểm tra thẩm thấu PT, rửa được sau kiểm tra. Bình xịt 500 ml và can 1–200 L. Fast Group báo giá kèm SDS. Bình xịt aerosol 500 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-bea/","category":"Chất thẩm thấu PT Diffu-Therm"},{"type":"Sản phẩm","code":"BEA-N","title":"Diffu-Therm BEA-N","desc":"Thuốc hiện hình, rửa được, điểm chớp cháy cao. Diffu-Therm BEA-N: thuốc hiện hình gốc dung môi, bản đóng can có điểm chớp cháy > 21°C nên dễ lưu kho và vận chuyển hơn. Bình xịt 500 ml, can 1–200 L. RFQ tại Fast Group. Bình xịt aerosol 500 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-bea-n/","category":"Chất thẩm thấu PT Diffu-Therm"},{"type":"Sản phẩm","code":"BEA-W","title":"Diffu-Therm BEA-W","desc":"Thuốc hiện hình gốc nước. Diffu-Therm BEA-W: thuốc hiện hình gốc nước, không chảy xệ ngay cả trên bề mặt dựng đứng, chỉ thị hiện rõ sau khi khô. Chỉ đóng can 1–200 L. Fast Group báo giá kèm SDS. Can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-bea-w/","category":"Chất thẩm thấu PT Diffu-Therm"},{"type":"Sản phẩm","code":"BEW","title":"Diffu-Therm BEW","desc":"Thuốc hiện hình chống lem. Diffu-Therm BEW: thuốc hiện hình gốc dung môi, không lem sau khi khô, chỉ thị giữ độ tương phản lâu — phù hợp khi cần chụp ảnh lưu hồ sơ nghiệm thu. Bình xịt aerosol 500 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-bew/","category":"Chất thẩm thấu PT Diffu-Therm"},{"type":"Sản phẩm","code":"BRE","title":"Diffu-Therm BRE","desc":"Dung dịch tẩy rửa đa năng. Diffu-Therm BRE: cleaner gốc dung môi dùng làm sạch trước kiểm tra và loại bỏ phần thẩm thấu dư, tẩy được mọi sản phẩm trong hệ. Bình xịt 500 ml, can 1–200 L. Bình xịt aerosol 500 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-bre/","category":"Chất thẩm thấu PT Diffu-Therm"},{"type":"Sản phẩm","code":"BRE-2","title":"Diffu-Therm BRE-2","desc":"Dung dịch tẩy rửa không làm tan lớp nền DPM. Diffu-Therm BRE-2: cleaner gốc dung môi không làm tan lớp sơn nền tương phản DPM — dùng cho quy trình MT có nền tương phản. Bình xịt 500 ml và can 1–200 L. Bình xịt aerosol 500 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-bre-2/","category":"Chất thẩm thấu PT Diffu-Therm"},{"type":"Sản phẩm","code":"BRE-3","title":"Diffu-Therm BRE-3","desc":"Dung dịch tẩy rửa không tan DPM, điểm chớp cháy cao. Diffu-Therm BRE-3: cleaner gốc dung môi không làm tan lớp nền DPM, bản đóng can có điểm chớp cháy > 21°C nên dễ lưu kho hơn. Bình xịt 500 ml, can 1–200 L. Bình xịt aerosol 500 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-bre-3/","category":"Chất thẩm thấu PT Diffu-Therm"},{"type":"Sản phẩm","code":"BRE-S","title":"Diffu-Therm BRE-S","desc":"Dung dịch tẩy rửa đa năng. Diffu-Therm BRE-S: cleaner gốc dung môi cho quy trình kiểm tra thẩm thấu PT, tẩy được mọi sản phẩm trong hệ. Bình xịt 500 ml và can 1–200 L. Fast Group báo giá kèm SDS. Bình xịt aerosol 500 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-bre-s/","category":"Chất thẩm thấu PT Diffu-Therm"},{"type":"Sản phẩm","code":"USR","title":"Diffu-Therm USR","desc":"Chất thẩm thấu màu đỏ cho gốm sứ và nhựa. Diffu-Therm USR: penetrant đỏ chuyên dùng cho gốm sứ và nhựa, rửa bằng nước, dải nhiệt 5…50°C. Chỉ đóng can 1–200 L, không có bản aerosol. RFQ tại Fast Group. Can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-usr/","category":"Chất thẩm thấu PT Diffu-Therm"},{"type":"Sản phẩm","code":"DPM","title":"Diffu-Therm DPM","desc":"Sơn nền tương phản. Diffu-Therm DPM: lớp sơn nền tương phản trắng phủ trước khi rắc bột từ, giúp chỉ thị bột từ đen nổi rõ trên bề mặt sẫm màu. Bình xịt 500 ml và can. RFQ tại Fast Group. Bình xịt aerosol 500 ml; can/thùng theo yêu cầu","url":"../san-pham/diffu-therm-dpm/","category":"Bột từ kiểm tra MT Diffu-Therm"},{"type":"Sản phẩm","code":"MPS-F","title":"Diffu-Therm MPS-F","desc":"Huyền phù bột từ huỳnh quang. Diffu-Therm MPS-F: huyền phù bột từ huỳnh quang quan sát dưới đèn UV-A, độ nhạy cao hơn bột từ đen, phát hiện khuyết tật nhỏ. Bình xịt 500 ml và can 1–200 L. Bình xịt aerosol 500 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-mps-f/","category":"Bột từ kiểm tra MT Diffu-Therm"},{"type":"Sản phẩm","code":"MPS-F2","title":"Diffu-Therm MPS-F2","desc":"Huyền phù bột từ huỳnh quang chịu nhiệt trung bình. Diffu-Therm MPS-F2: huyền phù bột từ huỳnh quang dùng cho bề mặt nóng 50–125°C, quan sát dưới đèn UV-A. Bình xịt 500 ml và can 1–200 L. Fast Group báo giá kèm SDS. Bình xịt aerosol 500 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-mps-f2/","category":"Bột từ kiểm tra MT Diffu-Therm"},{"type":"Sản phẩm","code":"MPS-F3","title":"Diffu-Therm MPS-F3","desc":"Huyền phù bột từ huỳnh quang chịu nhiệt cao. Diffu-Therm MPS-F3: huyền phù bột từ huỳnh quang làm việc đến 200°C — mã chịu nhiệt cao nhất nhóm MT, dùng cho thiết bị đang vận hành. Bình xịt 500 ml, can 1–200 L. Bình xịt aerosol 500 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-mps-f3/","category":"Bột từ kiểm tra MT Diffu-Therm"},{"type":"Sản phẩm","code":"MPS-FW","title":"Diffu-Therm MPS-FW","desc":"Huyền phù bột từ huỳnh quang, aerosol không thuộc hàng nguy hiểm. Diffu-Therm MPS-FW: huyền phù bột từ huỳnh quang có bản aerosol không thuộc nhóm hàng nguy hiểm — thuận lợi khi vận chuyển và lưu kho tại công trường. Can 1–200 L. Bình xịt aerosol 500 ml (không thuộc nhóm hàng nguy hiểm); can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-mps-fw/","category":"Bột từ kiểm tra MT Diffu-Therm"},{"type":"Sản phẩm","code":"MPS-S","title":"Diffu-Therm MPS-S","desc":"Huyền phù bột từ màu đen. Diffu-Therm MPS-S: huyền phù bột từ màu đen dùng cho kiểm tra hạt từ MT trên vật liệu sắt từ, làm việc đến 50°C. Bình xịt 500 ml và can 1–200 L. RFQ tại Fast Group. Bình xịt aerosol 500 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-mps-s/","category":"Bột từ kiểm tra MT Diffu-Therm"},{"type":"Sản phẩm","code":"MPS-S2","title":"Diffu-Therm MPS-S2","desc":"Huyền phù bột từ màu đen chịu nhiệt trung bình. Diffu-Therm MPS-S2: huyền phù bột từ đen dùng cho kiểm tra MT trên bề mặt nóng 50–125°C, ví dụ mối hàn chưa nguội hoặc thiết bị đang vận hành. Bình xịt 500 ml, can 1–200 L. Bình xịt aerosol 500 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-mps-s2/","category":"Bột từ kiểm tra MT Diffu-Therm"},{"type":"Sản phẩm","code":"MPS-SW","title":"Diffu-Therm MPS-SW","desc":"Huyền phù bột từ màu đen gốc nước. Diffu-Therm MPS-SW: huyền phù bột từ đen gốc nước, phù hợp khi nhà máy hạn chế dung môi hoặc kiểm tra trong không gian kín. Chỉ đóng can 5L, 10L, 30L. RFQ tại Fast Group. Can/thùng 5L, 10L, 30L","url":"../san-pham/diffu-therm-mps-sw/","category":"Bột từ kiểm tra MT Diffu-Therm"},{"type":"Sản phẩm","code":"CDR","title":"Diffu-Therm CDR","desc":"Chất thẩm thấu màu đỏ chịu nhiệt 200°C. Diffu-Therm CDR: penetrant đỏ hệ System C làm việc đến 200°C, dùng kiểm tra mối hàn chưa nguội và thiết bị đang nóng. Bình xịt 400 ml và can 1–200 L. RFQ tại Fast Group. Bình xịt aerosol 400 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-cdr/","category":"Hệ thống C đến 200°C Diffu-Therm"},{"type":"Sản phẩm","code":"CEA","title":"Diffu-Therm CEA","desc":"Thuốc hiện hình chịu nhiệt 200°C. Diffu-Therm CEA: thuốc hiện hình gốc dung môi của hệ System C, làm việc đến 200°C, dùng cặp với penetrant CDR. Bình xịt 400 ml và can 1–200 L. Fast Group báo giá kèm SDS. Bình xịt aerosol 400 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-cea/","category":"Hệ thống C đến 200°C Diffu-Therm"},{"type":"Sản phẩm","code":"CRE","title":"Diffu-Therm CRE","desc":"Dung dịch tẩy rửa chịu nhiệt 200°C. Diffu-Therm CRE: cleaner gốc dung môi của hệ System C, làm việc đến 200°C, dùng làm sạch trước và sau kiểm tra trên bề mặt nóng. Bình xịt 400 ml và can 1–200 L. Bình xịt aerosol 400 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-cre/","category":"Hệ thống C đến 200°C Diffu-Therm"},{"type":"Sản phẩm","code":"USF","title":"Diffu-Therm USF","desc":"Chất thẩm thấu huỳnh quang UV cho gốm sứ. Diffu-Therm USF: penetrant huỳnh quang rửa nước, chuyên dùng cho vật liệu gốm sứ. Chỉ đóng can 1–200 L, không có bản aerosol. RFQ tại Fast Group Engineering. Can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-usf/","category":"Hệ thống UV huỳnh quang Diffu-Therm"},{"type":"Sản phẩm","code":"UVE","title":"Diffu-Therm UVE","desc":"Thuốc hiện hình cho hệ UV. Diffu-Therm UVE: thuốc hiện hình gốc dung môi cho hệ thẩm thấu huỳnh quang UV, rửa được bằng nước. Bình xịt 400 ml và can 1–200 L. Fast Group báo giá kèm SDS. Bình xịt aerosol 400 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-uve/","category":"Hệ thống UV huỳnh quang Diffu-Therm"},{"type":"Sản phẩm","code":"UVE-W","title":"Diffu-Therm UVE-W","desc":"Thuốc hiện hình hệ UV gốc nước. Diffu-Therm UVE-W: thuốc hiện hình gốc nước cho hệ UV, không chảy xệ trên bề mặt dựng đứng, chỉ thị hiện rõ sau khi khô. Bình xịt 400 ml và can 1–200 L. Bình xịt aerosol 400 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-uve-w/","category":"Hệ thống UV huỳnh quang Diffu-Therm"},{"type":"Sản phẩm","code":"UVF-4","title":"Diffu-Therm UVF-4","desc":"Chất thẩm thấu huỳnh quang UV. Diffu-Therm UVF-4: penetrant huỳnh quang quan sát dưới đèn UV-A, rửa được bằng nước, độ nhạy cao hơn hệ PT màu đỏ. Bình xịt 400 ml và can 1–200 L. RFQ tại Fast Group. Bình xịt aerosol 400 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-uvf-4/","category":"Hệ thống UV huỳnh quang Diffu-Therm"},{"type":"Sản phẩm","code":"UVF-S","title":"Diffu-Therm UVF-S","desc":"Chất thẩm thấu huỳnh quang UV cho ngành thực phẩm. Diffu-Therm UVF-S: penetrant huỳnh quang rửa nước, được hãng chỉ định cho thiết bị ngành thực phẩm. Bình xịt 400 ml và can 1–200 L. Fast Group báo giá kèm SDS và chứng từ. Bình xịt aerosol 400 ml; can/thùng 1L, 5L, 10L, 30L, 200L","url":"../san-pham/diffu-therm-uvf-s/","category":"Hệ thống UV huỳnh quang Diffu-Therm"},{"type":"Sản phẩm","code":"UVP","title":"Diffu-Therm UVP","desc":"Bột hiện hình UV dạng khô. Diffu-Therm UVP: bột hiện hình dạng khô cho hệ thẩm thấu huỳnh quang UV, dùng cho buồng phun bột hoặc bể tầng sôi. Đóng gói 1 kg và 5 kg. RFQ tại Fast Group. Can/thùng 1 kg, 5 kg","url":"../san-pham/diffu-therm-uvp/","category":"Hệ thống UV huỳnh quang Diffu-Therm"},{"type":"Danh mục","code":"Penetrant testing PT","title":"Chất thẩm thấu PT Diffu-Therm","desc":"Dung dịch thẩm thấu, thuốc hiện hình và cleaner Diffu-Therm cho kiểm tra PT/NDT mối hàn, đúc, gia công cơ khí theo DIN EN ISO 3452 và ASME Section V.","url":"../kiem-tra-tham-thau-pt-diffu-therm/","category":"Danh mục"},{"type":"Danh mục","code":"Magnetic particle testing MT","title":"Bột từ kiểm tra MT Diffu-Therm","desc":"Bột từ, hỗn dịch từ đen/huỳnh quang và nền tương phản Diffu-Therm cho kiểm tra MT chi tiết ferromagnetic theo DIN EN ISO 9934-2.","url":"../kiem-tra-hat-tu-mt-diffu-therm/","category":"Danh mục"},{"type":"Danh mục","code":"High-temperature PT up to 200 C","title":"Hệ thống C đến 200°C Diffu-Therm","desc":"Bộ CDR, CEA, CRE Diffu-Therm cho kiểm tra thẩm thấu ở nhiệt độ đến 200°C, phục vụ bảo trì nóng, hàn và kiểm tra hiện trường.","url":"../he-thong-c-200c-diffu-therm/","category":"Danh mục"},{"type":"Danh mục","code":"Fluorescent penetrant testing UV","title":"Hệ thống UV huỳnh quang Diffu-Therm","desc":"Dung dịch thẩm thấu UV, developer UV và bột hiện hình Diffu-Therm cho kiểm tra huỳnh quang dưới đèn UV, phát hiện khuyết tật rất nhỏ.","url":"../he-thong-uv-huynh-quang-diffu-therm/","category":"Danh mục"},{"type":"Bài viết","code":"EN 10204 3.1B","title":"EN 10204 — 2.1, 2.2, 3.1, 3.2 khác nhau thế nào và khi nào dự án bắt buộc 3.1B","desc":"Giải thích bốn loại chứng từ theo EN 10204, vì sao 3.1B là loại hay bị yêu cầu nhất trong dự án dầu khí, và cách ghi đúng yêu cầu chứng từ vào RFQ vật tư NDT.","url":"../blog/en-10204-3-1b-chung-tu-vat-tu-ndt/","category":"Blog NDT"},{"type":"Bài viết","code":"lưu huỳnh halogen vật tư NDT","title":"Lưu huỳnh và halogen trong vật tư NDT — vì sao thép không gỉ austenit và hợp kim nickel bị giới hạn","desc":"Giải thích cơ chế ăn mòn ứng suất và giòn do lưu huỳnh, halogen tồn dư từ chất thẩm thấu và bột từ; vật liệu nào bị giới hạn, cần hỏi chứng từ gì và cách ghi vào RFQ.","url":"../blog/luu-huynh-halogen-vat-tu-ndt-thep-khong-gi/","category":"Blog NDT"},{"type":"Bài viết","code":"chỉ thị giả trong kiểm tra NDT","title":"Phân biệt chỉ thị thật và chỉ thị giả trong kiểm tra PT và MT","desc":"Ba loại chỉ thị trong PT và MT — chỉ thị thật, chỉ thị không liên quan và chỉ thị giả; nguyên nhân từng loại, cách xác nhận lại và cách tránh báo cáo sai.","url":"../blog/phan-biet-chi-thi-that-va-chi-thi-gia-pt-mt/","category":"Blog NDT"},{"type":"Bài viết","code":"chọn PT hay MT","title":"Chọn PT hay MT cho một mối hàn — cây quyết định và những chỗ hay chọn sai","desc":"So sánh kiểm tra thẩm thấu PT và kiểm tra hạt từ MT theo vật liệu, loại khuyết tật, điều kiện hiện trường và chi phí; kèm cây quyết định và các trường hợp phải dùng cả hai.","url":"../blog/chon-pt-hay-mt-cho-moi-han/","category":"Blog NDT"},{"type":"Bài viết","code":"tính lượng vật tư PT","title":"Tính lượng vật tư PT cần cho X mét mối hàn — phương pháp ước tính cho BOM và RFQ","desc":"Cách ước tính số bình xịt penetrant, developer và cleaner cần cho một khối lượng kiểm tra PT; các yếu tố làm tăng tiêu hao và cách tự hiệu chuẩn định mức cho nhà máy của mình.","url":"../blog/tinh-luong-vat-tu-pt-cho-met-moi-han/","category":"Blog NDT"},{"type":"Bài viết","code":"vận chuyển aerosol NDT","title":"Vận chuyển và nhập khẩu vật tư NDT dạng aerosol — phân loại hàng nguy hiểm và những ràng buộc cần biết trước","desc":"Vì sao bình xịt NDT là hàng nguy hiểm khi vận chuyển, đọc mục 14 của SDS thế nào, hạn chế với vận tải hàng không, và cách chọn mã hoặc quy cách để giảm rắc rối logistics.","url":"../blog/nhap-khau-van-chuyen-aerosol-ndt/","category":"Blog NDT"},{"type":"Bài viết","code":"shelf-life vật tư NDT","title":"Shelf-life, bảo quản và xử lý thải vật tư NDT — phần HSE hay bị bỏ quên trong hồ sơ","desc":"Vật tư NDT hết hạn ảnh hưởng kết quả kiểm tra thế nào, cách quản lý shelf-life theo lô, điều kiện lưu kho ở khí hậu Việt Nam, và nghĩa vụ xử lý chất thải sau kiểm tra.","url":"../blog/shelf-life-bao-quan-xu-ly-thai-vat-tu-ndt/","category":"Blog NDT"},{"type":"Bài viết","code":"BOM vật tư NDT","title":"Checklist lập BOM vật tư NDT cho dự án chế tạo — 9 hạng mục hay bị bỏ sót","desc":"Danh sách kiểm tra đầy đủ khi lập BOM vật tư kiểm tra không phá hủy cho dự án chế tạo skid, bồn bể, đường ống: từ vật liệu, tiêu chuẩn, chứng từ đến thiết bị đo và vật tư phụ.","url":"../blog/checklist-bom-vat-tu-ndt-du-an-che-tao/","category":"Blog NDT"},{"type":"Bài viết","code":"nhận dạng loại nứt","title":"Nứt mỏi, nứt do hàn hay nứt ăn mòn ứng suất — đọc hình dạng chỉ thị để đoán nguyên nhân","desc":"Hình dạng, vị trí và hướng của chỉ thị PT/MT cho biết loại nứt và nguyên nhân gây ra nó. Cách phân biệt nứt mỏi, nứt nóng, nứt nguội, nứt miệng hố và nứt ăn mòn ứng suất tại hiện trường.","url":"../blog/nhan-dang-nut-moi-nut-han-nut-an-mon-ung-suat/","category":"Blog NDT"},{"type":"Bài viết","code":"kiểm tra mối hàn ống theo công đoạn","title":"Kiểm tra mối hàn ống theo từng công đoạn — root, hot pass, cap và sau xử lý nhiệt","desc":"Kiểm tra bề mặt ở công đoạn nào, tìm khuyết tật gì, dùng PT hay MT, vì sao phải chờ thời gian trễ trước khi kiểm tra, và cách xếp các điểm dừng kiểm tra vào ITP.","url":"../blog/kiem-tra-moi-han-ong-theo-cong-doan-root-hot-pass-cap/","category":"Blog NDT"},{"type":"Bài viết","code":"ASTM E1417 vs ISO 3452","title":"ASTM E1417 và ISO 3452 — xử lý thế nào khi dự án có cả spec Mỹ lẫn châu Âu","desc":"Hai hệ tiêu chuẩn kiểm tra thẩm thấu khác nhau ở chỗ nào, vì sao không thể chọn cái dễ hơn, cách lập bảng đối chiếu tham số và những chỗ hay xung đột trong dự án đa tiêu chuẩn.","url":"../blog/astm-e1417-vs-iso-3452-du-an-hai-he-tieu-chuan/","category":"Blog NDT"},{"type":"Bài viết","code":"trộn vật tư NDT khác hãng","title":"Vì sao không nên ghép penetrant hãng A với developer hãng B","desc":"Hệ vật tư thẩm thấu được phê duyệt theo bộ, không theo từng sản phẩm rời. Bốn rủi ro khi trộn vật tư khác hãng, ba trường hợp ngoại lệ, và cách xử lý khi buộc phải thay thế giữa chừng.","url":"../blog/khong-nen-ghep-penetrant-hang-a-developer-hang-b/","category":"Blog NDT"},{"type":"Bài viết","code":"khử từ sau kiểm tra MT","title":"Khử từ sau kiểm tra hạt từ — khi nào bắt buộc, làm thế nào và ghi nhận ra sao","desc":"Từ dư sau kiểm tra MT gây arc blow khi hàn, mài mòn ở chi tiết chuyển động và sai lệch thiết bị đo. Khi nào phải khử từ, các phương pháp khử, cách đo từ dư và cách ghi vào biên bản.","url":"../blog/khu-tu-sau-kiem-tra-hat-tu-mt/","category":"Blog NDT"}];